async def cmd_assert_value(selector, expected_value):
    """Assert an input/textarea/select element's value equals expected_value."""
    ws_url, _ = get_page_ws()
    safe_sel = json.dumps(selector)
    strict = _replay_strict_rule()
    if strict is not None:
        # A replayed environment value: compared inside _VAR_TARGET_FN, never
        # put in a script, never printed (nor the field's actual value).
        find_js = f"""(function() {{
      {_SHADOW_QUERY_JS}
      /* cdpilot-var-find */
      var res = __cdpilot_resolveSelector(document, {safe_sel}, true);
      return res && res.el ? res.el : 'FAIL: Element not found: ' + {safe_sel};
    }})()"""
        out = await _replay_strict_act(ws_url, find_js, _replay_strict_value('assert-value', expected_value),
                                       strict, 'assert')
        if out.get('refused'):
            _replay_strict_refuse('assert-value', out['refused'])
        if not out.get('ok'):
            print(out.get('missing') or f'FAIL: Element not found: {selector}')
        elif out.get('equal'):
            print(f'PASS: Value matches ({selector}, value not shown)')
        else:
            print(f'FAIL: Value differs ({selector}, values not shown)')
        return
    safe_expected = json.dumps(expected_value)
    js = f"""(function() {{
      {_SHADOW_QUERY_JS}
      var res = __cdpilot_resolveSelector(document, {safe_sel}, true);
      if (!res || !res.el) return 'FAIL: Element not found: ' + {safe_sel};
      var el = res.el;
      var val = el.value;
      var expected = {safe_expected};
      var hostDesc = res.host ? __cdpilot_hostDesc(res.host) : null;
      var msg = val === expected ? 'PASS: Value matches \"' + expected + '\"' : 'FAIL: Expected value \"' + expected + '\" but got \"' + val + '\"';
      return {{ msg: msg, shadowHost: hostDesc }};
    }})()"""
    r = await cdp_send(ws_url, [(1, "Runtime.evaluate", {"expression": js, "returnByValue": True})])
    val = r.get(1, {}).get("result", {}).get("value")
    if isinstance(val, dict):
        if val.get("shadowHost"):
            _maybe_print_shadow_note(selector, val["shadowHost"])
        print(val.get("msg", "ERROR"))
    else:
        print(val or "ERROR")


